"""Hints (OA1-OA3 only), example walkthroughs and per-example explanations for the coding questions, keyed by source question id."""

HINTS = {
 # ------------------------------ SQL
 "n1": ["Which rows should be counted at all? Remove the others with WHERE before grouping.", "GROUP BY trader_id gives one row per trader; COUNT(*) and SUM(quantity) are computed per group.", "A condition on an aggregate (COUNT(*) >= 2) cannot go in WHERE — use HAVING. Finish with ORDER BY total_shares DESC, trader_id."],
 "n2": ["You need both tables: JOIN Trades to Securities on security_id.", "Notional is quantity * price for each trade — put the multiplication inside SUM(...).", "Filter FILLED trades in WHERE, GROUP BY the security, ROUND(SUM(...), 2), then ORDER BY total_notional DESC, ticker."],
 "n3": ["Purchases are rows with amount > 0. Dates are text 'YYYY-MM-DD HH:MM:SS', so they compare correctly as strings.", "Use txn_time >= '2025-01-01 00:00:00' AND txn_time < '2025-02-01 00:00:00' — a half-open range includes all of 31 January.", "GROUP BY channel, then HAVING COUNT(*) >= 2, ROUND(AVG(amount), 2) and the requested ORDER BY."],
 "oa02-sql-01": ["Only ACTIVE accounts and only purchases in the half-open January window should be counted — do this filtering in WHERE.", "JOIN Accounts to Transactions on account_id, then GROUP BY the account so each row summarises one account.", "HAVING COUNT(*) >= 2 is wrong here — the spec says at least 3 purchases. Finish with ROUND(SUM(amount), 2), MAX(amount) and ORDER BY total_amount DESC, account_id."],
 "oa05-sql-01": ["Runs without any predictions must still appear, so which join type do you need from ModelRuns to Predictions?", "COUNT(p.score) skips NULL scores, and SUM(CASE WHEN p.score >= r.threshold THEN 1 ELSE 0 END) counts flagged rows.", "Guard the division: when COUNT(p.score) = 0 return 0.0. COALESCE turns the NULL sum of an empty group into 0."],
 "oa02-sql-02": ["Start from Transactions, JOIN AccountProfiles to get the tier, and LEFT JOIN RiskAlerts so un-alerted transactions stay.", "One transaction can have several alerts, which multiplies rows — count with COUNT(DISTINCT ...).", "flagged_count = COUNT(DISTINCT a.txn_id); flag_rate = flagged / transactions. Use CASE to order HIGH, MEDIUM, LOW."],
 "n4a": ["Break the problem in two: first the sentiment statistics per entity, then the count of confirmed events per entity — two CTEs.", "For events use WHERE EXISTS (a preceding English article of the same entity within 24 hours). EXISTS cannot double-count an event.", "DATETIME(a.published_at, '+1 day') gives the end of the 24 h window. LEFT JOIN the event counts so companies with zero confirmed events show 0 (COALESCE)."],
 # ------------------------------ pandas
 "e1": ["Boolean conditions are combined with & and each condition needs parentheses: (df['side'] == 'BUY') & (df['qty'] >= 100).", "sort_values accepts a list of columns and a list for ascending, e.g. ascending=[False, True].", "Finish with out[['trade_id', 'ticker', 'qty', 'price']].reset_index(drop=True)."],
 "e2": ["Column arithmetic is element-wise: trades['qty'] * trades['price'] needs no loop.", "np.where(condition, value_if_true, value_if_false) works on whole columns.", "Copy the frame first, add the two columns, then select the six requested columns in order."],
 "e3": ["groupby('ticker') splits the data; named aggregation looks like .agg(n_trades=('trade_id', 'count'), ...).", "Use as_index=False so ticker stays a normal column.", "Sort with sort_values(['total_qty', 'ticker'], ascending=[False, True]) and reset the index."],
 "e4": ["Missing values are NaN; fillna replaces them. A single global mean is NOT what is asked — you need one mean per ticker.", "groupby('ticker')['price'].transform('mean') returns a Series aligned to the original rows.", "Fill qty with 0 and cast with astype('int64'); if a ticker has no price at all its mean is NaN, so the price stays NaN."],
 "e5": ["merge(left, right, on='ticker', how='left') keeps every trade.", "Unmatched trades get NaN in the right-hand columns — fillna('UNKNOWN') on name and sector.", "Sort by trade_id, select the five columns and reset the index."],
 "m1": ["pd.to_datetime(col, format=..., errors='coerce') turns invalid text into NaT; dropna removes them.", "The .dt accessor gives .dt.day_name(), .dt.dayofweek (Mon=0 … Sun=6), .dt.normalize(), .dt.hour and .dt.strftime('%Y-%m').", "is_weekend is dayofweek >= 5. Sort by txn_time then txn_id before selecting the columns."],
 "m2": ["Convert updated_at to datetime first, then sort so the latest row of each account is last.", "sort_values(kind='mergesort') is stable: rows with equal timestamps keep their input order.", "drop_duplicates('account_id', keep='last') keeps the final row of each account; then sort by account_id."],
 "m3": ["Sort by symbol and date first; every later step depends on that order.", "Inside groupby you can use .transform(lambda s: s.rolling(3, min_periods=1).mean()) and .cumsum().", "rank(method='min', ascending=False) gives 1 to the highest volume and equal values share the lower rank; cast to int64."],
 "oa01-pd-03": ["pivot_table(index='date', columns='symbol', values='ret', aggfunc='mean') collapses duplicate (date, symbol) pairs by averaging.", "wide.mean(axis=1) skips NaN by default; wide.notna().sum(axis=1) counts reporting symbols.", "Sort the symbol columns alphabetically, reset_index, and clear the columns' name with out.columns.name = None."],
 "oa02-pd-03": ["Drop rows with a missing amount before counting anything.", "Use named aggregation; pct_night is the mean of a boolean column. For night_total sum a helper column that is amount where is_night else 0.", "Filter n_txn >= 2 AFTER aggregating, then sort by total_amount DESC and account_id ASC."],
 "oa01-pd-01": ["Do the steps in the stated order: normalise the symbol, parse the timestamp, drop bad timestamps, then de-duplicate.", "drop_duplicates(subset=['symbol', 'ts'], keep='last') keeps the last row of each duplicate pair — before filtering prices.", "Finally keep rows with price > 0 (NaN fails this test too) and size > 0, sort by symbol and ts and reset the index."],
 "oa01-pd-02": ["Treat close <= 0 as missing with .where(df['close'] > 0).", "Forward fill must stay inside each symbol: df.groupby('symbol')['close'].ffill().", "daily_return = close / groupby('symbol')['close'].shift(1) - 1 gives NaN for first rows and rows next to a gap automatically."],
 "oa03-pd-03": ["After parsing timestamps and dropping invalid rows, de-duplicate (article_id, entity_id) keeping the last occurrence.", "dt.floor('6h') assigns every timestamp to its 6-hour bin start.", "groupby(['entity_id', 'bin_start']).agg(...) with ('score', 'mean'), ('article_id', 'nunique') and a lambda for the largest absolute score."],
 "oa04-pd-03": ["Group-wise statistics that must be broadcast back to every row are a job for groupby(...).transform(...).", "Series.quantile(0.25/0.75) per symbol; fences are q1 − 1.5·IQR and q3 + 1.5·IQR; Series.clip(lower=..., upper=...) accepts Series bounds.", "Symbols with fewer than 4 non-NaN returns must be left untouched — build a boolean 'active' mask from groupby(...)['ret'].transform('count') >= 4."],
 "oa05-pd-02": ["Parse ts and drop rows with a missing score first; then derive date with dt.normalize().", "Create boolean columns for tp, fp, fn, tn from (score >= threshold) and (y_true == 1) and sum them per day.", "Divide with .where(denominator > 0) so undefined ratios become NaN; Brier is the mean of (score − y_true)²."],
 # ------------------------------ DSA
 "da": ["If the list were sorted, which two items would you look at first?", "Keep two pointers: one at the cheapest, one at the most expensive item.", "If their sum fits the budget, remember it and move the left pointer right; otherwise move the right pointer left."],
 "db": ["You need to know how often every character occurs before you can decide which one is unique.", "A dictionary (or collections.Counter) built in one pass gives all counts.", "Second pass: return the first index whose character has count 1; otherwise -1."],
 "dc": ["What would make merging easy? Think about the order of the windows.", "Sort by start; then you only ever compare the next window with the last merged one.", "If next.start <= last.end, extend last.end to max(last.end, next.end); otherwise append a new window."],
 "oa03-dsa-01": ["First reduce the events to one total per entity name.", "A dictionary accumulates the totals in one pass over the events.", "You only need the best k: heapq.nsmallest(k, items, key=lambda kv: (-total, name)) encodes both the ranking and the tie-break."],
 "oa01-dsa-01": ["Brute force tries every triple (O(n³)). Can sorting help?", "Sort, fix the first element i, and use two pointers lo = i+1, hi = n−1 for the other two.", "If the sum is below the target move lo right, otherwise move hi left; keep the best sum, preferring the smaller sum on a tie."],
 "oa02-dsa-01": ["A window is balanced when #F − #N = 0. Track a running balance as you scan.", "Two prefixes with the same balance enclose a balanced window.", "Keep a dictionary balance → count of earlier prefixes (start with {0: 1}); every new prefix adds that many windows."],
}

